<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { api } from './api'

defineProps({currentUser:{type:Object,required:true}})
const flows=ref([]),selected=ref(null),graph=ref({nodes:[],edges:[]}),selectedNodeId=ref(null),connectFrom=ref(null),canvas=ref(null),search=ref(''),error=ref(''),success=ref(''),tags=ref([]),fields=ref([]),agents=ref([])
const createForm=reactive({name:'',trigger_type:'manual',trigger_value:''})
const draft=reactive({title:'',trigger_type:'manual',keywords:'',match_type:'exact',stop_on_reply:false,text:'',seconds:60,condition_field:'service_window',operator:'open',value:'',url:'',method:'POST',body:'',button_label:'',button_action:'next',action_value:''})

const definitions={
 trigger:{label:'Start Bot Flow',icon:'🤖',group:null,inputs:[],outputs:[['next','Compose Next Message']]},
 send_message:{label:'Text',icon:'💬',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},
 image:{label:'Image',icon:'🖼',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},
 video:{label:'Video',icon:'🎥',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},
 audio:{label:'Audio',icon:'🎵',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},
 file:{label:'File',icon:'📎',group:'Messages',inputs:[['input','Message']],outputs:[['next','Next']]},
 question:{label:'Question',icon:'❓',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next']]},
 interactive:{label:'Interactive Message',icon:'🔘',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next'],['buttons','Buttons'],['list_messages','List Messages'],['ecommerce','E-commerce']]},
 button:{label:'Button',icon:'↖',group:'Interactive',inputs:[['input','Reply']],outputs:[['next','Next'],['sequence','Subscribe to Sequence']]},
 template:{label:'Template Message',icon:'🧩',group:'Interactive',inputs:[['input','Message']],outputs:[['next','Next']]},
 add_tag:{label:'Add tag',icon:'🏷',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},
 remove_tag:{label:'Remove tag',icon:'✂',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},
 set_field:{label:'Set custom field',icon:'📝',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},
 assign_user:{label:'Assign agent',icon:'👤',group:'Contact',inputs:[['input','Action']],outputs:[['next','Next']]},
 condition:{label:'Condition',icon:'⑂',group:'Flow control',inputs:[['input','Reply']],outputs:[['yes','True'],['no','False']]},
 delay:{label:'Delay',icon:'⏱',group:'Flow control',inputs:[['input','Action']],outputs:[['next','Next']]},
 set_status:{label:'Conversation status',icon:'✓',group:'Flow control',inputs:[['input','Action']],outputs:[['next','Next']]},
 http_request:{label:'HTTP request',icon:'🌐',group:'Integrations',inputs:[['input','Action']],outputs:[['next','Next']]}
}
const groupOrder=['Messages','Interactive','Contact','Flow control','Integrations']
const groups=computed(()=>groupOrder.map(label=>({label,items:Object.entries(definitions).filter(([,d])=>d.group===label&&d.label.toLowerCase().includes(search.value.toLowerCase()))})).filter(g=>g.items.length))
const selectedNode=computed(()=>graph.value.nodes.find(n=>n.id===selectedNodeId.value)||null)
const def=n=>definitions[n?.node_type]||{label:n?.node_type||'Block',icon:'⚡',inputs:[['input','Input']],outputs:[['next','Next']]}
const nodeWidth=250
function portY(n,handle,kind='out'){const ports=kind==='out'?def(n).outputs:def(n).inputs;const i=Math.max(0,ports.findIndex(p=>p[0]===handle));return 82+i*25}
function nodeHeight(n){return Math.max(125,98+def(n).outputs.length*25)}
function nodeById(id){return graph.value.nodes.find(n=>n.id===id)}
function edgePath(e){const s=nodeById(e.source_node_id),t=nodeById(e.target_node_id);if(!s||!t)return'';const sx=s.position_x+nodeWidth,sy=s.position_y+portY(s,e.source_handle,'out'),tx=t.position_x,ty=t.position_y+portY(t,e.target_handle||'input','in'),dx=Math.max(70,Math.abs(tx-sx)*.45);return `M ${sx} ${sy} C ${sx+dx} ${sy}, ${tx-dx} ${ty}, ${tx} ${ty}`}
function summary(n){const c=n.config||{};if(n.node_type==='trigger')return c.trigger_value||c.trigger_type||'Manual';if(n.node_type==='send_message')return c.text||'Configure message';if(n.node_type==='condition')return `${c.field||'service_window'} ${c.operator||'open'} ${c.value||''}`.trim();if(n.node_type==='button')return c.label||'Configure button';if(n.node_type==='interactive')return c.text||'Please make a selection';if(n.node_type==='delay')return `${c.seconds||60}s`;if(n.node_type==='http_request')return `${c.method||'POST'} ${c.url||'Configure URL'}`;return n.title||def(n).label}
async function refs(){for(const [p,set] of [[api.contactTags(),tags],[api.contactFields(),fields],[api.agents(),agents]])try{set.value=await p}catch{}}
async function loadFlows(auto=true){try{flows.value=await api.flows();if(auto&&!selected.value&&flows.value.length)await selectFlow(flows.value[0])}catch(e){error.value=e.message}}
async function createFlow(){try{const f=await api.createFlow({name:createForm.name,trigger_type:createForm.trigger_type,trigger_value:createForm.trigger_type==='keyword'?createForm.trigger_value:null,stop_on_reply:false});createForm.name='';createForm.trigger_value='';await loadFlows(false);await selectFlow(f)}catch(e){error.value=e.message}}
async function selectFlow(flow){selected.value=await api.flow(flow.id||flow);graph.value=await api.flowGraph(selected.value.id);selectedNodeId.value=null;connectFrom.value=null;if(!graph.value.nodes.length)await seedGraph()}
async function seedGraph(){const trigger=await api.addFlowNode(selected.value.id,{node_type:'trigger',title:'Start Bot Flow',config:{trigger_type:selected.value.trigger_type,trigger_value:selected.value.trigger_value,match_type:'exact',stop_on_reply:selected.value.stop_on_reply},position_x:80,position_y:100});graph.value.nodes.push(trigger);let prev=trigger,y=100;for(const step of selected.value.steps||[]){const node=await api.addFlowNode(selected.value.id,{node_type:step.step_type,title:null,config:step.config||{},position_x:390,position_y:y});graph.value.nodes.push(node);graph.value.edges.push(await api.addFlowEdge(selected.value.id,{source_node_id:prev.id,source_handle:'next',target_node_id:node.id,target_handle:'input'}));prev=node;y+=170}}
async function addNode(type){if(!selected.value)return;const count=graph.value.nodes.length;const base=type==='delay'?{seconds:60}:type==='condition'?{field:'service_window',operator:'open',value:''}:type==='http_request'?{method:'POST',url:'',body:''}:type==='button'?{label:'Button',action:'next'}:type==='interactive'?{text:'Please make a selection'}:{};const node=await api.addFlowNode(selected.value.id,{node_type:type,title:def({node_type:type}).label,config:base,position_x:370+(count%3)*300,position_y:100+Math.floor(count/3)*190});graph.value.nodes.push(node);selectNode(node)}
function hydrate(n){const c=n?.config||{};Object.assign(draft,{title:n?.title||'',trigger_type:c.trigger_type||selected.value?.trigger_type||'manual',keywords:c.trigger_value||selected.value?.trigger_value||'',match_type:c.match_type||'exact',stop_on_reply:c.stop_on_reply??selected.value?.stop_on_reply??false,text:c.text||'',seconds:c.seconds||60,condition_field:c.field||'service_window',operator:c.operator||'open',value:c.value||'',url:c.url||'',method:c.method||'POST',body:c.body||'',button_label:c.label||'',button_action:c.action||'next',action_value:c.action_value||''})}
function selectNode(n){selectedNodeId.value=n.id;hydrate(n)}
async function saveNode(){const n=selectedNode.value;if(!n)return;let config={...(n.config||{})};if(n.node_type==='trigger'){config={...config,trigger_type:draft.trigger_type,trigger_value:draft.trigger_type==='keyword'?draft.keywords:null,match_type:draft.match_type,stop_on_reply:draft.stop_on_reply};selected.value=await api.updateFlow(selected.value.id,{name:draft.title||selected.value.name,trigger_type:config.trigger_type,trigger_value:config.trigger_value,stop_on_reply:config.stop_on_reply})}if(['send_message','interactive','question'].includes(n.node_type))config.text=draft.text;if(n.node_type==='button')config={...config,label:draft.button_label,action:draft.button_action,action_value:draft.action_value};if(n.node_type==='delay')config.seconds=Number(draft.seconds);if(n.node_type==='condition')config={...config,field:draft.condition_field,operator:draft.operator,value:draft.value};if(n.node_type==='http_request')config={...config,method:draft.method,url:draft.url,body:draft.body};const updated=await api.updateFlowNode(selected.value.id,n.id,{title:draft.title||null,config});graph.value.nodes[graph.value.nodes.findIndex(x=>x.id===n.id)]=updated;success.value='Changes saved.';setTimeout(()=>success.value='',1600)}
async function deleteNode(n){if(n.node_type==='trigger'||!confirm('Delete this block and its connections?'))return;await api.deleteFlowNode(selected.value.id,n.id);graph.value.nodes=graph.value.nodes.filter(x=>x.id!==n.id);graph.value.edges=graph.value.edges.filter(e=>e.source_node_id!==n.id&&e.target_node_id!==n.id);selectedNodeId.value=null}
async function dragEnd(ev,n){const r=canvas.value.getBoundingClientRect();n.position_x=Math.max(20,Math.round(ev.clientX-r.left-30+canvas.value.scrollLeft));n.position_y=Math.max(20,Math.round(ev.clientY-r.top-20+canvas.value.scrollTop));await api.updateFlowNode(selected.value.id,n.id,{position_x:n.position_x,position_y:n.position_y})}
function armConnection(n,handle){connectFrom.value={node_id:n.id,handle}}
async function connectTo(n,handle='input'){if(!connectFrom.value||connectFrom.value.node_id===n.id)return;try{graph.value.edges.push(await api.addFlowEdge(selected.value.id,{source_node_id:connectFrom.value.node_id,source_handle:connectFrom.value.handle,target_node_id:n.id,target_handle:handle}));connectFrom.value=null}catch(e){error.value=e.message}}
async function deleteEdge(e){await api.deleteFlowEdge(selected.value.id,e.id);graph.value.edges=graph.value.edges.filter(x=>x.id!==e.id)}
async function updateStatus(status){selected.value=await api.updateFlow(selected.value.id,{status});await loadFlows(false)}
onMounted(()=>{loadFlows();refs()})
</script>

<template>
<section class="vfb">
 <aside class="palette"><div class="palette-head"><b>Flow blocks</b><small>Click a block to add it</small></div><input v-model="search" placeholder="Search blocks…"><div class="groups"><section v-for="g in groups" :key="g.label"><h4>{{g.label}}</h4><button v-for="[type,d] in g.items" :key="type" @click="addNode(type)"><span>{{d.icon}}</span>{{d.label}}</button></section></div></aside>
 <main class="main"><header class="toolbar"><div class="flow-picker"><select v-if="flows.length" :value="selected?.id||''" @change="selectFlow(Number($event.target.value))"><option v-for="f in flows" :key="f.id" :value="f.id">{{f.name}}</option></select><form @submit.prevent="createFlow"><input v-model="createForm.name" required placeholder="New flow…"><select v-model="createForm.trigger_type"><option value="manual">Manual</option><option value="keyword">Keyword</option><option value="first_message">First message</option></select><input v-if="createForm.trigger_type==='keyword'" v-model="createForm.trigger_value" required placeholder="Keyword"><button>Create</button></form></div><div v-if="selected"><span :class="['state',selected.status]">{{selected.status}}</span><select :value="selected.status" @change="updateStatus($event.target.value)"><option value="draft">Draft</option><option value="active">Active</option><option value="paused">Paused</option></select></div></header>
  <div v-if="selected" ref="canvas" class="stage" @click.self="connectFrom=null"><svg class="edges"><path v-for="e in graph.edges" :key="e.id" :d="edgePath(e)" @dblclick="deleteEdge(e)"/></svg>
   <article v-for="n in graph.nodes" :key="n.id" class="node" :class="[n.node_type,{selected:selectedNodeId===n.id}]" :style="{left:n.position_x+'px',top:n.position_y+'px',minHeight:nodeHeight(n)+'px'}" draggable="true" @dragend="dragEnd($event,n)" @click.stop="selectNode(n)"><header><span>{{def(n).icon}}</span><strong>{{n.title||def(n).label}}</strong><button v-if="n.node_type!=='trigger'" @click.stop="deleteNode(n)">×</button></header><p>{{summary(n)}}</p>
    <div v-for="([handle,label],i) in def(n).inputs" :key="'i'+handle" class="port-row input" :style="{top:(70+i*25)+'px'}"><button @click.stop="connectTo(n,handle)"></button><span>{{label}}</span></div>
    <div v-for="([handle,label],i) in def(n).outputs" :key="'o'+handle" class="port-row output" :style="{top:(70+i*25)+'px'}"><span>{{label}}</span><button :class="{armed:connectFrom?.node_id===n.id&&connectFrom?.handle===handle}" @click.stop="armConnection(n,handle)"></button></div>
   </article><div v-if="connectFrom" class="hint">Connecting <b>{{connectFrom.handle}}</b> — choose an input port · click canvas to cancel</div>
  </div>
 </main>
 <aside v-if="selectedNode" class="drawer"><div class="drawer-head"><div class="ico">{{def(selectedNode).icon}}</div><div><h2>Configure {{def(selectedNode).label}}</h2><p>Define how this block behaves.</p></div></div><div class="scroll"><section><h3>⚙ Basic Setup</h3><label>Title<input v-model="draft.title"></label>
  <template v-if="selectedNode.node_type==='trigger'"><label>Trigger type<select v-model="draft.trigger_type"><option value="keyword">Keyword</option><option value="first_message">First message</option><option value="manual">Manual</option></select></label><label v-if="draft.trigger_type==='keyword'">Trigger keywords<textarea v-model="draft.keywords" rows="4" placeholder="hello,hi,help"></textarea></label><div class="match"><button :class="{active:draft.match_type==='exact'}" @click="draft.match_type='exact'">Exact keyword match</button><button :class="{active:draft.match_type==='contains'}" @click="draft.match_type='contains'">String match</button></div><label class="check"><input v-model="draft.stop_on_reply" type="checkbox"> Stop flow when contact replies</label></template>
  <label v-if="['send_message','interactive','question'].includes(selectedNode.node_type)">Message<textarea v-model="draft.text" rows="6"></textarea></label>
  <template v-if="selectedNode.node_type==='button'"><label>Button label<input v-model="draft.button_label" placeholder="e.g. View audits"></label><label>Action<select v-model="draft.button_action"><option value="next">Continue to next block</option><option value="start_flow">Start a flow</option><option value="send_message">Send message</option><option value="url">Open URL</option></select></label><label v-if="draft.button_action!=='next'">Action value<input v-model="draft.action_value" placeholder="Flow ID, message or URL"></label></template>
  <label v-if="selectedNode.node_type==='delay'">Delay in seconds<input v-model.number="draft.seconds" type="number" min="1"></label>
  <template v-if="selectedNode.node_type==='condition'"><label>Check<select v-model="draft.condition_field"><option value="service_window">24-hour service window</option><option value="tag">Contact tag</option><option value="custom_field">Custom field</option><option value="conversation_status">Conversation status</option><option value="assigned_user">Assigned agent</option></select></label><label>Operator<select v-model="draft.operator"><option value="open">Open / is</option><option value="closed">Closed / is not</option><option value="equals">Equals</option><option value="not_equals">Not equals</option><option value="contains">Contains</option><option value="empty">Empty</option><option value="not_empty">Not empty</option></select></label><label>Value<input v-model="draft.value"></label></template>
  <template v-if="selectedNode.node_type==='http_request'"><label>Method<select v-model="draft.method"><option>GET</option><option>POST</option><option>PUT</option><option>PATCH</option><option>DELETE</option></select></label><label>URL<input v-model="draft.url" placeholder="https://…"></label><label>Request body<textarea v-model="draft.body" rows="6"></textarea></label></template>
 </section><section class="ports-info"><h3>↗ Connection ports</h3><p><b>Inputs:</b> {{def(selectedNode).inputs.map(x=>x[1]).join(', ')||'None'}}</p><p><b>Outputs:</b> {{def(selectedNode).outputs.map(x=>x[1]).join(', ')||'None'}}</p></section></div><footer><button @click="selectedNodeId=null">× Close</button><button class="save" @click="saveNode">▣ Save Changes</button></footer></aside>
 <p v-if="error" class="toast error">{{error}}</p><p v-if="success" class="toast">{{success}}</p>
</section>
</template>

<style scoped>
*{box-sizing:border-box}.vfb{height:calc(100vh - 0px);min-height:720px;display:flex;background:#f4f8f6;color:#17231d;position:relative;overflow:hidden}.palette{width:260px;flex:0 0 260px;background:#fff;border-right:1px solid #dce5e0;z-index:5;overflow:auto}.palette-head{padding:20px 18px 12px;display:flex;flex-direction:column}.palette-head b{font-size:18px}.palette-head small{color:#7d8d85}.palette>input{margin:0 12px 12px;width:calc(100% - 24px);padding:11px;border:1px solid #d8e2dd;border-radius:9px}.groups section{padding:4px 12px 12px}.groups h4{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:#8b9b93;margin:8px 0}.groups button{width:100%;border:0;border-bottom:1px solid #edf1ef;background:#fff;text-align:left;padding:11px 6px;cursor:pointer}.groups button:hover{background:#eff8f3}.groups button span{display:inline-block;width:27px}.main{flex:1;min-width:0;display:flex;flex-direction:column}.toolbar{height:66px;flex:0 0 66px;background:#fff;border-bottom:1px solid #dce5e0;display:flex;align-items:center;justify-content:space-between;padding:10px 18px}.flow-picker,.flow-picker form{display:flex;gap:7px}.toolbar input,.toolbar select,.toolbar button{border:1px solid #d5e0da;border-radius:8px;background:#fff;padding:9px}.toolbar button{background:#18aa5b;color:#fff;border-color:#18aa5b;font-weight:700}.state{margin-right:8px;text-transform:uppercase;font-size:10px;font-weight:800;padding:5px 8px;border-radius:12px;background:#eaf5ef}.stage{position:relative;flex:1;overflow:auto;min-width:1200px;min-height:700px;background-image:radial-gradient(#dbe6e0 1px,transparent 1px);background-size:22px 22px}.edges{position:absolute;left:0;top:0;width:4000px;height:2500px;pointer-events:none}.edges path{fill:none;stroke:#6f8279;stroke-width:2.2;pointer-events:stroke;cursor:pointer}.edges path:hover{stroke:#18aa5b;stroke-width:4}.node{position:absolute;width:250px;background:#fff;border:1px solid #dbe4df;border-radius:12px;box-shadow:0 6px 18px rgba(22,57,40,.09);padding-bottom:36px;cursor:grab}.node.selected{border:2px solid #18aa5b}.node header{height:44px;padding:0 12px;display:flex;align-items:center;gap:7px;border-bottom:1px solid #edf1ef}.node header strong{flex:1;font-size:14px}.node header button{border:0;background:transparent;color:#a33;font-size:18px;cursor:pointer}.node>p{margin:11px 15px 10px;font-size:12px;color:#6e7e76;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.port-row{position:absolute;height:25px;display:flex;align-items:center;gap:6px;font-size:10px;color:#315646}.port-row button{width:13px;height:13px;border:2px solid #607a6d;background:#fff;border-radius:50%;cursor:pointer;padding:0}.port-row button:hover,.port-row button.armed{background:#18aa5b;border-color:#18aa5b}.port-row.input{left:-7px}.port-row.output{right:-7px}.port-row.input span{margin-left:2px}.port-row.output span{margin-right:2px}.condition .port-row.output span{text-transform:uppercase;font-weight:800}.hint{position:sticky;left:50%;top:15px;width:max-content;background:#123c2b;color:#fff;border-radius:20px;padding:8px 13px;font-size:12px;z-index:10}.drawer{width:520px;flex:0 0 520px;background:#fff;border-left:1px solid #dce5e0;z-index:20;display:flex;flex-direction:column;box-shadow:-8px 0 25px rgba(22,57,40,.08)}.drawer-head{display:flex;gap:12px;padding:20px;border-bottom:1px solid #e5ece8}.ico{width:42px;height:42px;border-radius:10px;background:#e8f8ef;display:grid;place-items:center}.drawer h2{font-size:19px;margin:0}.drawer-head p{margin:3px 0 0;color:#7b8a83;font-size:12px}.scroll{padding:16px;overflow:auto;flex:1}.scroll section{border:1px solid #dce5e0;border-radius:12px;padding:16px;margin-bottom:14px}.scroll h3{margin:0 0 14px;font-size:14px}.scroll label{display:block;font-size:12px;font-weight:700;margin:12px 0}.scroll input,.scroll select,.scroll textarea{display:block;width:100%;margin-top:5px;border:1px solid #d4dfd9;border-radius:8px;padding:10px;background:#fff}.match{display:grid;grid-template-columns:1fr 1fr;gap:8px}.match button{padding:12px;border:1px solid #d5dfda;background:#fff;border-radius:8px}.match button.active{border-color:#18aa5b;background:#eefaf3}.check{display:flex!important;align-items:center;gap:7px}.check input{width:auto;margin:0}.ports-info p{font-size:12px;color:#617269}.drawer footer{padding:14px 16px;border-top:1px solid #dce5e0;display:flex;justify-content:space-between}.drawer footer button{padding:10px 16px;border:1px solid #d5dfda;border-radius:8px;background:#fff;font-weight:700}.drawer footer .save{background:#18aa5b;border-color:#18aa5b;color:#fff}.toast{position:fixed;bottom:22px;right:22px;background:#e8f8ef;color:#17643d;padding:10px 16px;border-radius:8px;z-index:50}.toast.error{background:#fdecec;color:#a22}@media(max-width:1100px){.drawer{width:420px;flex-basis:420px}.palette{width:220px;flex-basis:220px}}
</style>
